#!/usr/bin/env python3
"""JP Contábil — sincroniza a API do Acessórias e gera o Dashboard de Indicadores (HTML único).

Uso:  ACESSORIAS_TOKEN=xxxx [PAINEL_SENHA=yyyy] python3 jp_dashboard.py [--out index.html] [--hoje AAAA-MM-DD]
Janela: mês atual + 2 meses anteriores. Com PAINEL_SENHA, os dados saem criptografados (requer: pip install cryptography).
Somente leitura (GET). Respeita o limite de 100 requisições/minuto da API.
"""
import os, sys, json, time, gzip, base64, re, argparse, datetime as dt, urllib.request, urllib.parse, urllib.error
from collections import deque

API = 'https://api.acessorias.com'
TEMPLATE_GZ_B64 = ''

# ---------------------------------------------------------------- HTTP
class Api:
    def __init__(self, token, per_min=90):
        self.h = {'Authorization': 'Bearer ' + token, 'Accept': 'application/json', 'User-Agent': 'JP-Dashboard/1.0'}
        self.win = deque(); self.per_min = per_min; self.calls = 0
    def _wait(self):
        now = time.monotonic()
        while self.win and now - self.win[0] > 60: self.win.popleft()
        if len(self.win) >= self.per_min:
            time.sleep(60 - (now - self.win[0]) + 0.2)
        self.win.append(time.monotonic())
    def get(self, path, params=None):
        url = API + path + (('?' + urllib.parse.urlencode(params)) if params else '')
        for tent in range(8):
            self._wait(); self.calls += 1
            try:
                with urllib.request.urlopen(urllib.request.Request(url, headers=self.h), timeout=90) as r:
                    if r.status == 204: return None
                    b = r.read()
                    if not b.strip(): return None
                    return json.loads(b.decode('utf-8'))
            except urllib.error.HTTPError as e:
                if e.code in (204, 404): return None
                if e.code == 401: sys.exit('Token inválido (HTTP 401).')
                time.sleep(15 if e.code == 429 else 5 * (tent + 1))
            except Exception:
                time.sleep(5 * (tent + 1))
        raise RuntimeError('Falha repetida em ' + url)
    def pages(self, path, params, size, key=None, max_pages=5000):
        max_pages = int(os.environ.get('JP_MAX_PAGES', '0') or 0) or max_pages
        out = []
        for pg in range(1, max_pages + 1):
            d = self.get(path, {**params, 'Pagina': pg})
            if d is None: break
            items = d.get(key, []) if (key and isinstance(d, dict)) else (d if isinstance(d, list) else [d])
            if not items: break
            out.extend(items)
            if len(items) < size: break
        return out

# ---------------------------------------------------------------- helpers
def d_iso(s):
    if not s or s.startswith('0000'): return None
    try: return dt.date.fromisoformat(s[:10])
    except ValueError: return None
def d_br(s):
    if not s: return None
    try: return dt.datetime.strptime(s[:19], '%d/%m/%Y %H:%M:%S')
    except ValueError:
        try: return dt.datetime.strptime(s[:10], '%d/%m/%Y')
        except ValueError: return None
EPOCH = dt.date(1970, 1, 1)
def eday(d):
    if d is None: return None
    if isinstance(d, dt.datetime): d = d.date()
    return (d - EPOCH).days
def ym(d): return d.strftime('%Y-%m')
def add_months(d, k):
    m = d.month - 1 + k; y = d.year + m // 12; return dt.date(y, m % 12 + 1, 1)
def last_day(d): return add_months(d, 1) - dt.timedelta(days=1)
digits = lambda s: re.sub(r'\D', '', s or '')

def regime_grupo(reg, mei_tag, filial_tag):
    if mei_tag: return 'MEI'
    r = (reg or '').strip()
    if filial_tag or r.lower().startswith('filial'): return 'Filial'
    low = r.lower()
    for pre, g in [('lucro presumido', 'Lucro Presumido'), ('lucro real', 'Lucro Real'), ('mei', 'MEI'), ('simples nacional', 'Simples Nacional'),
                   ('imune', 'Imune/Isenta'), ('rural', 'Rural'), ('doméstica', 'Domésticas'), ('domestica', 'Domésticas'), ('autônomo', 'Autônomo/Prof. Liberal'), ('autonomo', 'Autônomo/Prof. Liberal')]:
        if low.startswith(pre): return g
    return 'Sem regime'

SIT = {'Ent. antecipada': 'Entregue antecipada', 'Ent. PzTéc': 'Entregue no prazo técnico', 'Ent. atrasada': 'Entregue com atraso', 'Ent. justificada': 'Entregue com atraso',
       'Dispensada': 'Dispensada', 'Atrasada!': 'Em aberto - atrasada', 'Atraso justificado': 'Em aberto - atrasada', 'Pendente': 'Em aberto - no prazo', 'Prazo técnico': 'Em aberto - prazo técnico'}
def situacao(st, prazo, atraso, entrega, hoje):
    if st in SIT: return SIT[st]
    s = (st or '').lower()
    if 'dispens' in s: return 'Dispensada'
    if entrega:
        if prazo and entrega <= prazo: return 'Entregue antecipada'
        if atraso and entrega <= atraso: return 'Entregue no prazo técnico'
        return 'Entregue com atraso'
    if atraso and hoje > atraso: return 'Em aberto - atrasada'
    if prazo and hoje > prazo: return 'Em aberto - prazo técnico'
    return 'Em aberto - no prazo'
def guia(v):
    s = (v or '').lower().strip()
    if not s: return 'Sem envio de guia'
    if 'falta' in s: return 'Não enviada (falta de informação)'
    if 'não' in s or 'nao' in s: return 'Não lida'
    if 'lida' in s or 'acessada' in s: return 'Lida pelo cliente'
    return 'Outro'

# ---------------------------------------------------------------- sync
def sync(token, hoje, log=print):
    api = Api(token)
    ref = add_months(hoje.replace(day=1), -1)            # mês anterior (referência padrão do painel)
    ini = add_months(hoje.replace(day=1), -2)             # janela: mês atual + 2 anteriores
    fim = last_day(hoje.replace(day=1))                   # até o fim do mês atual
    log(f'Referência {ym(ref)} · prazos {ini} a {fim}')

    # empresas ativas + tags
    comps = api.pages('/companies/ListAll/', {'ativa': 'S', 'obligations': 'S', 'registrationData': 'S'}, 20)
    def tag_ids(tid):
        d = api.get(f'/tags/{tid}/', {'companies': 'S'}) or []
        d = d if isinstance(d, list) else [d]
        return {str(c.get('id')) for t in d for c in (t.get('companies') or [])}
    mei_ids, fil_ids = tag_ids(117), tag_ids(15)
    users = {str(u.get('id')): (u.get('nome') or '').strip() for u in (api.pages('/users/ListAll/', {}, 20) or [])}
    empresas = []
    for c in comps:
        nome = (c.get('Razao') or '').strip()
        if re.match(r'^grupo\s*\d+', nome, re.I): continue
        empresas.append(c)
    lim = int(os.environ.get('JP_MAX_EMP', '0') or 0)
    if lim: empresas = empresas[:lim]
    grupo = {str(c['ID']): regime_grupo(c.get('Regime'), str(c['ID']) in mei_ids, str(c['ID']) in fil_ids) for c in empresas}
    log(f'{len(empresas)} empresas ativas · {api.calls} chamadas')

    # entregas por empresa
    ents = []
    for k, c in enumerate(empresas):
        doc = digits(c.get('Identificador'))
        if not doc: continue
        lst = api.pages(f'/deliveries/{doc}/', {'DtInitial': ini.isoformat(), 'DtFinal': fim.isoformat(), 'config': 'S'}, 50, key='Entregas')
        for e in lst: e['_emp'] = c
        ents.extend(lst)
        if k % 50 == 0: log(f'  entregas: {k}/{len(empresas)} empresas · {len(ents)} entregas · {api.calls} chamadas')
    log(f'{len(ents)} entregas')

    # solicitações abertas no período
    sols = api.pages('/requests/ListAll/', {'SolAberturaIni': ini.isoformat(), 'SolAberturaFim': hoje.isoformat()}, 20)
    log(f'{len(sols)} solicitações · {api.calls} chamadas')

    # processos: iniciados no período + concluídos/previstos no período (iniciados antes)
    procs = {}
    for p in api.pages('/processes/ListAll/', {'ProcInicioIni': ini.isoformat()}, 20): procs[p['ProcID']] = p
    for p in api.pages('/processes/ListAll/', {'ProcConclusaoIni': ini.isoformat(), 'ProcInicioFim': (ini - dt.timedelta(days=1)).isoformat()}, 20): procs[p['ProcID']] = p
    log(f'{len(procs)} processos · {api.calls} chamadas no total')
    return dict(hoje=hoje, ref=ref, ini=ini, fim=fim, empresas=empresas, grupo=grupo, ents=ents, sols=sols, procs=list(procs.values()), users=users, calls=api.calls)

# ---------------------------------------------------------------- transformação (mesmo formato do painel)
def build_data(R):
    hoje, ini, fim = R['hoje'], R['ini'], R['fim']
    meses = []; d = ini
    while d <= fim: meses.append(ym(d)); d = add_months(d, 1)
    mi = {m: i for i, m in enumerate(meses)}
    dicts = {k: {} for k in ['comp', 'obr', 'tipo', 'depE', 'pess', 'stA', 'sitE', 'emp', 'reg', 'venc', 'guia', 'stS', 'sitS', 'tipoS', 'por', 'prio', 'depS', 'respS', 'stP', 'mat', 'tit', 'depP', 'gest', 'regA', 'grpE', 'uf']}
    def enc(name, v):
        if v is None: return None
        v = str(v).strip(); dd = dicts[name]
        if v not in dd: dd[v] = len(dd)
        return dd[v]
    for n, vals in [('tipo', ['Obrigação', 'Tarefa']), ('sitE', ['Entregue antecipada', 'Entregue no prazo técnico', 'Entregue com atraso', 'Em aberto - no prazo', 'Em aberto - prazo técnico', 'Em aberto - atrasada', 'Dispensada']),
                    ('venc', ['Concluída', 'Dispensada', 'Vencida', 'Vence em até 7 dias', 'A vencer (mais de 7 dias)']), ('guia', ['Sem envio de guia', 'Lida pelo cliente', 'Não lida', 'Não enviada (falta de informação)', 'Outro']),
                    ('sitS', ['Finalizada', 'Em aberto']), ('por', ['Cliente', 'Escritório']), ('stP', ['Concluído', 'Em andamento', 'Desistência'])]:
        for v in vals: enc(n, v)
    grupo = R['grupo']

    E = {k: [] for k in ['m', 'prazo', 'atraso', 'entrega', 'comp', 'obr', 'tipo', 'dep', 'resp', 'quem', 'stA', 'sit', 'emp', 'reg', 'multa', 'venc', 'dias', 'guia']}
    for e in R['ents']:
        prazo, atraso, entrega = d_iso(e.get('EntDtPrazo')), d_iso(e.get('EntDtAtraso')), d_iso(e.get('EntDtEntrega'))
        if not prazo or ym(prazo) not in mi: continue
        cfg = e.get('Config') or {}; c = e['_emp']; st = (e.get('Status') or '').strip()
        sit = situacao(st, prazo, atraso, entrega, hoje)
        entregue = sit.startswith('Entregue')
        if sit == 'Dispensada': venc = 'Dispensada'
        elif entregue: venc = 'Concluída'
        elif prazo < hoje: venc = 'Vencida'
        elif prazo <= hoje + dt.timedelta(days=7): venc = 'Vence em até 7 dias'
        else: venc = 'A vencer (mais de 7 dias)'
        quem = (cfg.get('RespEntrega') or e.get('RespEntrega') or '').strip() or None
        E['m'].append(mi[ym(prazo)]); E['prazo'].append(eday(prazo)); E['atraso'].append(eday(atraso)); E['entrega'].append(eday(entrega) if entregue else None)
        E['comp'].append(enc('comp', (e.get('EntCompetencia') or '')[:7] or '—')); E['obr'].append(enc('obr', re.sub(r'\s+', ' ', e.get('Nome') or '').strip()))
        E['tipo'].append(enc('tipo', 'Tarefa' if cfg.get('Tipo') == 'T' else 'Obrigação')); E['dep'].append(enc('depE', cfg.get('DptoNome') or '(sem departamento)'))
        E['resp'].append(enc('pess', (cfg.get('RespPrazo') or '').strip() or '(sem responsável)')); E['quem'].append(enc('pess', quem) if (quem and entregue) else None)
        E['stA'].append(enc('stA', st or '—')); E['sit'].append(enc('sitE', sit)); E['emp'].append(enc('emp', (c.get('Razao') or '').strip()))
        E['reg'].append(enc('reg', grupo.get(str(c['ID']), 'Sem regime'))); E['multa'].append(1 if e.get('EntMulta') == 'S' else 0)
        E['venc'].append(enc('venc', venc)); E['dias'].append((entrega - prazo).days if (entregue and entrega) else None); E['guia'].append(enc('guia', guia(e.get('EntGuiaLida'))))

    S = {k: [] for k in ['id', 'm', 'ab', 'fin', 'dias', 'stA', 'sit', 'tipo', 'por', 'prio', 'assunto', 'dep', 'resp', 'emp', 'reg', 'nota', 'idade']}
    for s in R['sols']:
        ab = d_br(s.get('SolDHAbertura'))
        if not ab or ym(ab) not in mi: continue
        stx = (s.get('SolStatus') or '').strip(); fin = stx == 'Finalizada'; fd = d_br(s.get('SolDHFinalizacao')) if fin else None
        nota = s.get('SolAvaliacao'); nota = int(nota) if str(nota or '').strip().isdigit() else None
        S['id'].append(int(s['SolID'])); S['m'].append(mi[ym(ab)]); S['ab'].append(eday(ab)); S['fin'].append(eday(fd))
        S['dias'].append(round((fd - ab).total_seconds() / 86400, 2) if fd else None); S['stA'].append(enc('stS', stx or '—')); S['sit'].append(enc('sitS', 'Finalizada' if fin else 'Em aberto'))
        S['tipo'].append(enc('tipoS', s.get('SolTipo') or '—')); S['por'].append(enc('por', 'Cliente' if (s.get('SolTipoUsuario') or '').startswith('Extern') else 'Escritório'))
        S['prio'].append(enc('prio', s.get('SolPrioridade') or '—')); S['assunto'].append((s.get('SolAssunto') or '').strip()); S['dep'].append(enc('depS', s.get('DptoNome') or '(sem departamento)'))
        S['resp'].append([enc('respS', r) for r in (s.get('SolOfficeResp') or []) if str(r).strip()]); S['emp'].append(enc('emp', (s.get('EmpNome') or '').strip()))
        S['reg'].append(enc('reg', grupo.get(str(s.get('EmpID')), 'Fora da carteira ativa'))); S['nota'].append(nota)
        S['idade'].append(None if fin else (hoje - ab.date()).days)

    plist = R['procs']; pm = set()
    for p in plist:
        a, b = d_br(p.get('ProcInicio')), d_br(p.get('ProcConclusao'))
        if a: pm.add(ym(a))
        if b: pm.add(ym(b))
    pmeses = sorted(pm); pmi = {m: i for i, m in enumerate(pmeses)}
    P = {k: [] for k in ['id', 'mi', 'mc', 'ini', 'con', 'st', 'mat', 'tit', 'dep', 'gest', 'dias', 'pct', 'pv', 'emp', 'reg']}
    for p in plist:
        a, b = d_br(p.get('ProcInicio')), d_br(p.get('ProcConclusao')); st = (p.get('ProcStatus') or '').strip()
        try: dias = int(float(p.get('ProcDiasCorridos') or 0))
        except ValueError: dias = None
        try: pct = round(float(p.get('ProcPorcentagem') or 0) / 100, 3)
        except ValueError: pct = None
        gid = str(p.get('ProcGestor') or '')
        P['id'].append(int(p['ProcID'])); P['mi'].append(pmi.get(ym(a)) if a else None); P['mc'].append(pmi.get(ym(b)) if b else None)
        P['ini'].append(eday(a)); P['con'].append(eday(b)); P['st'].append(enc('stP', st or '—')); P['mat'].append(enc('mat', re.sub(r'\s+', ' ', p.get('ProcNome') or '').strip()))
        P['tit'].append(enc('tit', (p.get('ProcTitulo') or '').strip())); P['dep'].append(enc('depP', p.get('ProcDepartamento') or '(sem departamento)'))
        P['gest'].append(enc('gest', R['users'].get(gid) or (gid or '(sem gestor)'))); P['dias'].append(dias); P['pct'].append(pct)
        P['pv'].append(1 if (st == 'Em andamento' and b and b.date() < hoje) else 0); P['emp'].append(enc('emp', (p.get('EmpNome') or '').strip()))
        P['reg'].append(enc('reg', grupo.get(str(p.get('EmpID')), 'Fora da carteira ativa')))

    C = {k: [] for k in ['id', 'doc', 'nome', 'fant', 'reg', 'regA', 'cad', 'nova', 'obr', 'grp', 'uf']}
    for c in R['empresas']:
        cad = d_iso(c.get('DataDoCadastro'))
        C['id'].append(int(c['ID'])); C['doc'].append(c.get('Identificador') or ''); C['nome'].append(enc('emp', (c.get('Razao') or '').strip()))
        C['fant'].append((c.get('Fantasia') or '').strip()); C['reg'].append(enc('reg', grupo[str(c['ID'])])); C['regA'].append(enc('regA', (c.get('Regime') or '').strip() or '(vazio)'))
        C['cad'].append(eday(cad)); C['nova'].append(1 if (cad and cad.year == R['ref'].year) else 0)
        C['obr'].append(sum(1 for o in (c.get('Obrigacoes') or []) if (o.get('Status') or '') == 'Ativa'))
        C['grp'].append(enc('grpE', c.get('GrupoDeEmpresas') or '—')); C['uf'].append(enc('uf', c.get('UF') or '—'))

    agora = dt.datetime.now(dt.timezone(dt.timedelta(hours=-3)))
    meta = dict(gerado=agora.strftime('%d/%m/%Y %H:%M'), hoje=eday(hoje), ano=R['ref'].year, mesAtual=ym(hoje), refMes=ym(R['ref']),
                prazoIni=eday(ini), prazoFim=eday(fim), chamadas=R['calls'])
    return dict(meta=meta, meses=meses, pmeses=pmeses, dicts={k: list(v) for k, v in dicts.items()}, E=E, S=S, P=P, C=C)

def render(data, artifact=False):
    tpl = gzip.decompress(base64.b64decode(TEMPLATE_GZ_B64)).decode('utf-8')
    if artifact:  # versão para link publicado: sem esqueleto próprio, cópia em vez de download
        tpl = tpl.replace('/*__ARTIFACT__*/false', 'true')
        for x in ['<!doctype html>', '<html lang="pt-BR">', '<head>', '</head>', '<body>', '</body>', '</html>', '<meta charset="utf-8">', '<meta name="viewport" content="width=device-width, initial-scale=1">']:
            tpl = tpl.replace(x, '', 1)
        tpl = tpl.replace('.top{position:sticky;top:0;', '.top{position:sticky;top:env(safe-area-inset-top,0px);', 1)
    raw = gzip.compress(json.dumps(data, ensure_ascii=False, separators=(',', ':')).encode('utf-8'), 9)
    senha = os.environ.get('PAINEL_SENHA', '')
    if senha:  # AES-256-GCM com chave PBKDF2-SHA256; o navegador decifra com a mesma senha (WebCrypto)
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
        from cryptography.hazmat.primitives import hashes
        salt, iv, n = os.urandom(16), os.urandom(12), 310000
        key = PBKDF2HMAC(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=n).derive(senha.encode('utf-8'))
        raw = AESGCM(key).encrypt(iv, raw, None)
        enc = json.dumps({'s': base64.b64encode(salt).decode(), 'i': base64.b64encode(iv).decode(), 'n': n})
        tpl = tpl.replace('/*__ENC__*/null', enc)
    return tpl.replace('__DATA_B64__', base64.b64encode(raw).decode())

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--out', default='Dashboard_Indicadores_JP.html')
    ap.add_argument('--hoje', default=None, help='data de referência AAAA-MM-DD (padrão: hoje em Brasília)')
    ap.add_argument('--raw', default=None, help='salva/usa o JSON bruto da API (para depuração)')
    ap.add_argument('--artifact', default=None, help='também gera a versão para o link publicado neste caminho')
    a = ap.parse_args()
    hoje = dt.date.fromisoformat(a.hoje) if a.hoje else dt.datetime.now(dt.timezone(dt.timedelta(hours=-3))).date()
    t0 = time.time()
    if a.raw and os.path.exists(a.raw):
        R = json.load(open(a.raw, encoding='utf-8'), object_hook=None)
        for k in ['hoje', 'ref', 'ini', 'fim']: R[k] = dt.date.fromisoformat(R[k])
    else:
        token = os.environ.get('ACESSORIAS_TOKEN') or sys.exit('Defina ACESSORIAS_TOKEN.')
        R = sync(token, hoje, log=lambda m: print(time.strftime('%H:%M:%S'), m, flush=True))
        if a.raw:
            json.dump({**R, **{k: R[k].isoformat() for k in ['hoje', 'ref', 'ini', 'fim']}}, open(a.raw, 'w', encoding='utf-8'), ensure_ascii=False)
    data = build_data(R)
    html = render(data)
    open(a.out, 'w', encoding='utf-8').write(html)
    if a.artifact: open(a.artifact, 'w', encoding='utf-8').write(render(data, artifact=True))
    E, S, P = data['E'], data['S'], data['P']
    print(json.dumps({'arquivo': a.out, 'MB': round(len(html.encode()) / 1e6, 2), 'entregas': len(E['m']), 'solicitacoes': len(S['id']), 'processos': len(P['id']),
                      'empresas': len(data['C']['id']), 'referencia': data['meta']['refMes'], 'chamadas': data['meta']['chamadas'], 'minutos': round((time.time() - t0) / 60, 1)}, ensure_ascii=False))

if __name__ == '__main__':
    main()
